/* Panouri: Primăria (administrator complet) · Admin platformă · Firmă parteneră. Formulare cu previzualizare live a telefonului. */
const ORG = () => (S.adminRole === 'business' ? firm().name : S.adminRole === 'admin' ? 'Administrare' : 'Primăria Arad');
const SPARK = { a: [3, 4, 4, 5, 6, 5, 8], b: [10, 14, 18, 22, 26, 31, 38], c: [2, 3, 5, 6, 8, 9, 12], d: [1, 1, 2, 2, 2, 3, 3], e: [40, 52, 61, 70, 88, 95, 110] };
function evThumbStyle(e) { return e.img ? `background-image:url('${e.img}')` : `background:${e.tone}`; }
function tbl(cols, rows) { return `<table><thead><tr>${cols.map(c => `<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`; }
function segs(cur, items, act) { return `<div class="seg">${items.map(([k, l]) => `<button class="${cur === k ? 'on' : ''}" data-act="${act}" data-arg="${k}">${l}</button>`).join('')}</div>`; }

/* ---------- Panou Primărie / Dashboard Admin ---------- */
route('/city', () => cityDash()); route('/admin', () => cityDash(true));
function cityDash(admin) {
  const acts = A.pubActions(); const regs = A.allRegs(); const pts = regs.filter(r => r.status === 'CONFIRMED').reduce((s, r) => s + (A.allActions().find(a => a.id === r.action) || {}).pts || 0, 0) + 9870;
  const feed = S.scans.slice(-6).reverse().map(s => `<div><span class="fi">${ms(s.kind === 'offer' ? 'sell' : 'qr_code_scanner')}</span><div><b>${esc(s.who || 'Client')}</b> ${s.kind === 'offer' ? 'a folosit un cod de ofertă' : s.status === 'CONFIRMED' ? `confirmat de ${esc(s.by)} · +${s.pts} puncte` : `respins de ${esc(s.by)}`}<div class="ts">${s.at}</div></div></div>`).concat(Object.entries(S.msgs).flatMap(([v, arr]) => arr.map(m => `<div><span class="fi">${ms('forum')}</span><div><b>${esc((A.allVols().find(x => x.id === v) || {}).name)}</b>: „${esc(m.text)}”<div class="ts">${m.at}</div></div></div>`)));
  const kp = admin ? kpi('group', 'Utilizatori', '1.248', '+212 săpt. asta', SPARK.e, '#1D5FD1') + kpi('calendar_month', 'Evenimente publicate', A.pubEvents().length, '', SPARK.a) + kpi('confirmation_number', 'Bilete emise', 412 + S.tickets.length, '', SPARK.b) + kpi('stars', 'Puncte acordate', A.nf(pts), '3 acțiuni', SPARK.c, '#FF5A36') + kpi('sell', 'Coduri folosite', 187 + S.scans.filter(s => s.kind === 'offer').length, '', SPARK.c, '#8A5A00')
    : kpi('calendar_month', 'Evenimente în agendă', A.pubEvents().filter(e => e.date >= A.TODAY).length, '+2', SPARK.a) + kpi('group', 'Înscriși la acțiuni', acts.reduce((s, a) => s + a.taken, 0) + S.regs.length, '+12%', SPARK.b) + kpi('stars', 'Puncte acordate', A.nf(pts), '+40', SPARK.c, '#FF5A36') + kpi('badge', 'Voluntari activi', A.allVols().filter(v => v.status === 'ACTIVE').length, '', SPARK.d, '#1D5FD1');
  return { title: admin ? 'Dashboard' : 'Panou', body: `<div class="head"><div><h1>${admin ? 'Dashboard' : 'Bună dimineața, Primăria Arad'}</h1><div class="sub">${A.dayLong(A.TODAY)} 2026 · ${admin ? 'ultimele 30 de zile' : 'date de exemplu'}</div></div><div class="row"><a class="btn sec" href="#/city/events/new">${ms('add', 'xs')} Eveniment</a><a class="btn" href="#/city/actions/new">${ms('add', 'xs')} Acțiune comunitară</a></div></div>
    <div class="kpis ${admin ? 'k5' : ''}">${kp}</div>
    <div class="agrid2"><div class="acard"><div class="ch"><div><h2>${admin ? 'De verificat / moderat' : 'Participare la acțiuni'}</h2><div class="hint">${admin ? 'Firme noi și conținut în ciornă' : 'Înscriși față de locurile disponibile'}</div></div><a class="btn sm sec" href="#${admin ? '/city/partners' : '/city/validate'}">Toate ${ms('chevron_right', 'xs')}</a></div>
      ${admin ? A.allBiz().filter(b => !b.verified).map(b => `<div class="hbar" style="grid-template-columns:minmax(0,1fr) auto auto;padding:8px 0;border-bottom:1px solid var(--aline)"><div class="tcell"><div class="thumb" style="background-image:url('${b.img}')"></div><div><div class="tt">${esc(b.name)}</div><div class="ts">${esc(b.cat)} · ${esc(b.addr)} · ${b.since}</div></div></div><button class="btn sm sec" data-act="firmVerify" data-arg="${b.id}:0">Respinge</button><button class="btn sm ok" data-act="firmVerify" data-arg="${b.id}:1">${ms('verified', 'xs')} Verifică</button></div>`).join('') + A.allEvents().filter(e => e.status === 'DRAFT').map(e => `<div class="hbar" style="grid-template-columns:minmax(0,1fr) auto auto;padding:8px 0"><div class="tcell"><div class="thumb" style="${evThumbStyle(e)}">${e.img ? '' : e.emoji}</div><div><div class="tt">${esc(e.title)}</div><div class="ts">eveniment · ${esc(e.org.name)} · ciornă</div></div></div><span class="pill p-mut">Ciornă</span><button class="btn sm" data-act="setStatus" data-arg="ev:${e.id}:PUBLISHED">Publică</button></div>`).join('')
      : `<div class="hbars">${acts.map(a => { const r = regs.filter(x => x.action === a.id); return `<div class="hbar"><div class="tcell"><div class="thumb" style="${evThumbStyle(a)}">${a.img ? '' : a.emoji}</div><div><div class="tt">${esc(a.title)}</div><div class="ts">${A.dayLabel(a.date)} · ${r.filter(x => x.status === 'PENDING').length} de validat</div></div></div><div class="bar"><i style="width:${Math.round((a.taken + r.length) / a.spots * 100)}%"></i></div><span class="ts">${a.taken + S.regs.filter(x => x.action === a.id).length}/${a.spots}</span></div>`; }).join('')}</div>`}</div>
      <div class="acard"><div class="ch"><div><h2>Activitate</h2><div class="hint">Scanări, mesaje și publicări</div></div></div><div class="feed">${feed.length ? feed.join('') : empty('inbox', 'Încă nicio activitate', 'Scanările voluntarilor și mesajele apar aici.')}</div></div></div>` };
}
ACT.firmVerify = a => { const [id, v] = a.split(':'); S.firmVerified[id] = v === '1'; save(); toast(v === '1' ? 'Firmă verificată. Conținutul ei devine public.' : 'Firmă respinsă.', v === '1' ? 'verified' : 'block'); render(); };
ACT.setStatus = a => { const [k, id, st] = a.split(':'); A.setOverride(k + ':' + id, { status: st }); toast(st === 'PUBLISHED' ? 'Publicat în aplicație.' : st === 'HIDDEN' ? 'Ascuns din aplicație.' : 'Stare schimbată.', 'check_circle'); render(); };

/* ---------- Evenimente (agenda orașului) ---------- */
route('/city/events', () => {
  const f = UI.tmp.cef || 'all'; let l = A.allEvents().filter(e => !e.past); if (f === 'mine') l = l.filter(e => e.org.type === 'CITY'); if (f === 'free') l = l.filter(e => e.ticket === 'FREE'); if (f === 'draft') l = l.filter(e => e.status === 'DRAFT'); if (f === 'biz') l = l.filter(e => e.org.type === 'BUSINESS');
  return { title: 'Evenimente', body: `<div class="head"><div><h1>Evenimente</h1><div class="sub">Agenda orașului, așa cum apare în aplicație: instituții (link extern), firme partenere, Primărie.</div></div><a class="btn" href="#/city/events/new">${ms('add', 'xs')} Eveniment nou</a></div>
    <div class="acard flush"><div class="toolbar">${segs(f, [['all', 'Toate'], ['mine', 'Publicate de Primărie'], ['biz', 'Firme'], ['free', 'Gratuite'], ['draft', 'Ciorne']], 'cef')}<span class="count">${l.length} evenimente</span></div>
    ${tbl(['Eveniment', 'Organizator', 'Data și ora', 'Loc', 'Preț', 'Participă', 'Stare', ''], l.map(e => `<tr><td><div class="tcell"><div class="thumb" style="${evThumbStyle(e)}">${e.img ? '' : e.emoji}</div><div><div class="tt">${esc(e.title)}</div><div class="ts">${A.CATS[e.cat].l}${e.demo ? ' · demo' : ''}</div></div></div></td><td>${esc(e.org.name)}</td><td>${A.whenLabel(e)}</td><td>${esc(e.venue)}</td><td>${A.priceLabel(e)}</td><td>${e.participants ? A.nf(e.participants) + (A.isHot(e) ? ' 🔥' : '') : '—'}</td><td>${pill(e.status || 'PUBLISHED')}</td><td class="row" style="gap:6px;justify-content:flex-end">${(e.status || 'PUBLISHED') === 'PUBLISHED' ? `<button class="btn sm sec" data-act="setStatus" data-arg="ev:${e.id}:HIDDEN">Ascunde</button>` : `<button class="btn sm" data-act="setStatus" data-arg="ev:${e.id}:PUBLISHED">Publică</button>`}<a class="btn sm sec" href="#/events/${e.id}">Vezi</a></td></tr>`))}</div>` };
});
ACT.cef = a => { UI.tmp.cef = a; render(); };
const VENUES = [['pc', 'Palatul Cultural'], ['tc', 'Teatrul Clasic „Ioan Slavici”'], ['cs', 'Piața Catedralei'], ['fm', 'Faleza Mureșului'], ['ca', 'Cetatea Aradului (exterior)'], ['pa', 'Platoul Palatului Administrativ'], ['ce', 'Pădurea Ceala']];
function evPreview() { const f = UI.form; const v = A.byId(A.PLACES, f.venue) || A.PLACES[1]; const free = (f.ticket || 'FREE') === 'FREE'; return `<div class="pcard"><div class="pimg" style="${f.img ? `background-image:url('${f.img}')` : 'background:#7E3A3A'}">${f.img ? '' : (A.CATS[f.cat] || A.CATS.CONCERT).e}</div><div class="pbody"><span style="font-size:12px;color:#5C5C5C">${f.date ? A.dayLabel(f.date) : 'Sâm., 7 nov.'} · ${f.time || '19:00'}</span><b style="font-size:16px;color:${f.title ? '#111' : '#9a9a9a'}">${esc(f.title || 'Titlul evenimentului')}</b><span style="font-size:12.5px;color:#5C5C5C">${esc(v.name)} · ${A.km(v.dist)}</span><div style="margin-top:6px"><span class="pchip" style="position:static;background:${free ? '#E5F2E3' : '#111'};color:${free ? '#2F7D32' : '#fff'}">${free ? 'Gratuit · fără bilet' : (f.priceAdult || 40) + ' lei · bilete în aplicație'}</span></div></div></div>`; }
route('/city/events/new', () => { if (UI.formFor !== 'ev') { UI.form = { cat: 'CONCERT', venue: 'pc', date: '2026-11-07', time: '19:00', ticket: 'FREE', priceAdult: 40, priceChild: 25, capacity: 100 }; UI.formFor = 'ev'; } UI.previewFn = evPreview; const f = UI.form; const biz = S.adminRole === 'business';
  return { title: 'Eveniment nou', crumbs: [ORG(), 'Evenimente', 'Nou'], body: `<div class="head"><div><h1>Eveniment nou</h1><div class="sub">${biz ? 'Apare în agenda publică alături de cele ale instituțiilor' + (firm().verified ? '.' : ', după verificarea firmei (până atunci rămâne ciornă).') : 'Apare în agenda din aplicație, la data aleasă.'}</div></div></div>
    <div class="form"><div class="fcard"><div class="fsec">Detalii</div>${field('Titlu', 'title', 'text', { ph: 'Ex.: Concert de muzică de cameră' })}<div class="two">${field('Categorie', 'cat', 'select', { options: Object.entries(A.CATS).map(([k, c]) => [k, c.l]) })}${biz ? field('Locul', 'venueTxt', 'text', { value: 'La noi, ' + firm().addr }) : field('Locul', 'venue', 'select', { options: VENUES })}</div><div class="three">${field('Data', 'date', 'date')}${field('Ora', 'time', 'time')}${field('Durata (min)', 'dur', 'number', { ph: '90' })}</div>
      <div class="fsec">Intrare</div>${field('Bilete', 'ticket', 'seg', { options: [['FREE', 'Gratuit'], ['IN_APP', 'Cu bilet în aplicație'], ['EXTERNAL', 'Pe site extern']] })}${f.ticket === 'IN_APP' ? `<div class="three">${field('Preț adult (lei)', 'priceAdult', 'number')}${field('Preț copil (lei)', 'priceChild', 'number')}${field('Locuri', 'capacity', 'number')}</div>` : f.ticket === 'EXTERNAL' ? field('Link bilete', 'url', 'url', { ph: 'https://…' }) : ''}
      ${field('Descriere', 'desc', 'textarea', { ph: 'Ce se întâmplă, pentru cine e, ce trebuie să știe oamenii.' })}<div class="fsec">Poză</div>${field('Poză', 'img', 'drop')}
      <div class="actions"><button class="btn sec" data-act="evSave" data-arg="DRAFT">Salvează ciornă</button><button class="btn" data-act="evSave" data-arg="PUBLISHED">${ms('publish', 'xs')} ${biz && !firm().verified ? 'Trimite spre publicare' : 'Publică în aplicație'}</button></div></div>${phonePreview(evPreview())}</div>` }; });
ACT.evSave = st => { const f = UI.form; if (!f.title) { toast('Scrie un titlu.'); return; } const biz = S.adminRole === 'business'; const v = A.byId(A.PLACES, f.venue) || A.PLACES[1]; const fb = firm(); const id = 'nev' + Date.now(); const status = biz && !fb.verified ? 'DRAFT' : st; S.created.events.push({ id, title: f.title, cat: f.cat || 'CONCERT', date: f.date || '2026-11-07', time: f.time || '19:00', dur: +f.dur || undefined, placeId: biz ? undefined : v.id, bizId: biz ? fb.id : undefined, venue: biz ? fb.name : v.name, addr: biz ? fb.addr : v.addr, lat: biz ? fb.lat : v.lat, lng: biz ? fb.lng : v.lng, ticket: f.ticket || 'FREE', priceAdult: +f.priceAdult || 0, priceChild: +f.priceChild || 0, capacity: +f.capacity || 0, participants: 0, saves: 0, tone: '#7E3A3A', emoji: (A.CATS[f.cat] || A.CATS.CONCERT).e, img: f.img, org: biz ? { type: 'BUSINESS', name: fb.name, bizId: fb.id } : { type: 'CITY', name: 'Primăria Arad' }, demo: true, status, desc: f.desc || '', dist: biz ? fb.dist : v.dist, url: f.url, times: f.ticket === 'IN_APP' ? [{ d: f.date || '2026-11-07', t: f.time || '19:00', left: +f.capacity || 100 }] : undefined }); save(); UI.formFor = null; toast(status === 'PUBLISHED' ? 'Publicat. Apare acum în aplicație.' : 'Salvat ca ciornă.', 'check_circle'); go(biz ? '/business/events' : '/city/events'); };

/* ---------- Acțiuni comunitare ---------- */
route('/city/actions', () => { const f = UI.tmp.caf || 'up'; const l = A.allActions().filter(a => f === 'up' ? a.status === 'PUBLISHED' : f === 'draft' ? a.status === 'DRAFT' : true);
  return { title: 'Acțiuni comunitare', body: `<div class="head"><div><h1>Acțiuni comunitare</h1><div class="sub">Localnicii se înscriu, primesc un cod QR, voluntarii voștri confirmă prezența pe teren.</div></div><a class="btn" href="#/city/actions/new">${ms('add', 'xs')} Acțiune nouă</a></div>
    <div class="acard flush"><div class="toolbar">${segs(f, [['up', 'Urmează'], ['all', 'Toate'], ['draft', 'Ciorne']], 'caf')}<span class="count">${l.length} acțiuni</span></div>${tbl(['Acțiune', 'Când', 'Puncte', 'Locuri', 'Voluntari', 'Stare', ''], l.map(a => { const regs = A.allRegs().filter(r => r.action === a.id); const vols = A.allVols().filter(v => v.actions.includes(a.id)); return `<tr><td><div class="tcell"><div class="thumb" style="${evThumbStyle(a)}">${a.img ? '' : a.emoji}</div><div><div class="tt">${esc(a.title)}</div><div class="ts">${a.cat} · ${esc(a.place)}</div></div></div></td><td>${A.dayLabel(a.date)} · ${a.time}–${a.end}</td><td><span class="pill p-ok">+${a.pts}</span></td><td><div class="row"><div class="bar"><i style="width:${Math.round((a.taken + S.regs.filter(r => r.action === a.id).length) / a.spots * 100)}%"></i></div><span class="ts">${a.taken + S.regs.filter(r => r.action === a.id).length}/${a.spots}</span></div></td><td>${vols.map(v => `<span class="chip sm" style="height:24px;font-size:11.5px">${esc(v.name)}</span>`).join(' ') || '<span class="ts">niciunul</span>'}</td><td>${pill(a.status)}</td><td class="row" style="gap:6px;justify-content:flex-end">${a.status === 'DRAFT' ? `<button class="btn sm" data-act="setStatus" data-arg="ac:${a.id}:PUBLISHED">Publică</button>` : `<a class="btn sm sec" href="#/city/validate?a=${a.id}">Validare (${regs.filter(r => r.status === 'PENDING').length})</a>`}<button class="btn sm sec" data-act="na">Editează</button></td></tr>`; }))}</div>` }; });
ACT.caf = a => { UI.tmp.caf = a; render(); };
function actPreview() { const f = UI.form; const d = A.dayParts(f.date || '2026-11-21'); return `<div class="pcard"><div class="pimg" style="${f.img ? `background-image:url('${f.img}')` : 'background:#4F7A3A'}">${f.img ? '' : '🌳'}<div class="datechip"><span>${d.dow}</span><b>${d.n}</b><span>${d.mon}</span></div><span class="pchip" style="right:12px;top:12px;background:#E4EFDA;color:#1F3A12">+${f.pts || 50} puncte</span></div><div class="pbody"><b style="font-size:16px;color:${f.title ? '#111' : '#9a9a9a'}">${esc(f.title || 'Titlul acțiunii')}</b><span style="font-size:12.5px;color:#5C5C5C">${f.time || '09:00'}–${f.end || '12:00'} · ${esc(f.place || 'Locul de întâlnire')}</span><span style="font-size:12px;color:#5C5C5C">0/${f.spots || 20} locuri · ${esc(f.dept || 'Primăria Arad')}</span></div></div>`; }
route('/city/actions/new', () => { if (UI.formFor !== 'act') { UI.form = { cat: 'Mediu', date: '2026-11-21', time: '09:00', end: '12:00', pts: '50', spots: '20', vols: [] }; UI.formFor = 'act'; } UI.previewFn = actPreview;
  return { title: 'Acțiune nouă', crumbs: ['Primăria Arad', 'Acțiuni comunitare', 'Nouă'], body: `<div class="head"><div><h1>Acțiune comunitară nouă</h1><div class="sub">Apare în Comunitate; localnicii se pot înscrie imediat după publicare.</div></div></div>
    <div class="form"><div class="fcard"><div class="fsec">Detalii</div>${field('Titlu', 'title', 'text', { ph: 'Ex.: Plantăm flori în Parcul Copiilor' })}<div class="two">${field('Categorie', 'cat', 'select', { options: [['Mediu', 'Mediu'], ['Sănătate', 'Sănătate'], ['Social', 'Social'], ['Cultură', 'Cultură']] })}${field('Partener / direcție', 'dept', 'text', { ph: 'Direcția Spații Verzi' })}</div><div class="three">${field('Ziua', 'date', 'date')}${field('De la', 'time', 'time')}${field('Până la', 'end', 'time')}</div>${field('Locul de întâlnire', 'place', 'text', { ph: 'Ex.: Parcul Copiilor, intrarea principală' })}
      <div class="fsec">Puncte și locuri</div>${field('Puncte pentru fiecare participant', 'pts', 'chips', { options: [['30', '30'], ['50', '50'], ['60', '60'], ['80', '80'], ['100', '100']] })}${field('Număr de locuri', 'spots', 'chips', { options: [['20', '20'], ['40', '40'], ['60', '60'], ['100', '100']] })}${field('Descriere', 'desc', 'textarea', { ph: 'Ce facem, ce aduc oamenii, pentru cine e potrivit.' })}
      <div class="fsec">Voluntari care scanează</div>${field('Alocă voluntari', 'vols', 'checks', { options: A.allVols().map(v => [v.id, v.name, 'coordonator ' + v.coord]) })}<div class="fsec">Poză</div>${field('Poză', 'img', 'drop')}
      <div class="actions"><button class="btn sec" data-act="actSave" data-arg="DRAFT">Salvează ciornă</button><button class="btn" data-act="actSave" data-arg="PUBLISHED">${ms('publish', 'xs')} Publică</button></div></div>${phonePreview(actPreview())}</div>` }; });
ACT.actSave = st => { const f = UI.form; if (!f.title) { toast('Scrie un titlu.'); return; } const id = 'nc' + Date.now(); S.created.actions.push({ id, title: f.title, cat: f.cat, date: f.date, time: f.time, end: f.end, pts: +f.pts, spots: +f.spots, taken: 0, place: f.place || 'Arad', lat: 46.176 + Math.random() * .004, lng: 21.316 + Math.random() * .006, img: f.img, emoji: '🌳', tone: '#4F7A3A', dept: f.dept || 'Primăria Arad', status: st, desc: f.desc || '', going: [] }); (f.vols || []).forEach(vid => { const v = A.allVols().find(x => x.id === vid); A.setOverride('vo:' + vid, { actions: v.actions.concat([id]) }); }); save(); UI.formFor = null; toast(st === 'PUBLISHED' ? 'Acțiune publicată în aplicație.' : 'Salvată ca ciornă.', 'check_circle'); go('/city/actions'); };

/* ---------- Validare participanți ---------- */
route('/city/validate', (p, q) => { const acts = A.pubActions(); const cur = acts.find(a => a.id === (q.a || UI.tmp.va)) || acts[0]; UI.tmp.va = cur.id; const regs = A.allRegs().filter(r => r.action === cur.id); const conf = regs.filter(r => r.status === 'CONFIRMED');
  return { title: 'Validare participanți', crumbs: ['Primăria Arad', 'Comunitate', 'Validare'], body: `<div class="head"><div><h1>Validare participanți</h1><div class="sub">${esc(cur.title)} · ${A.dayLabel(cur.date)} · ${cur.time}–${cur.end} · ${esc(cur.place)}</div></div><div class="row">${segs(cur.id, acts.map(a => [a.id, a.emoji + ' ' + a.title.split(' ').slice(0, 2).join(' ')]), 'va')}</div></div>
    <div class="kpis">${kpi('group', 'Înscriși', `${regs.length + cur.taken - regs.length} / ${cur.spots}`)}${kpi('check_circle', 'Confirmați', conf.length, `+${conf.length * cur.pts} puncte acordate`)}${kpi('hourglass_top', 'În așteptare', regs.filter(r => r.status === 'PENDING').length)}${kpi('block', 'Neprezentați', regs.filter(r => r.status === 'NO_SHOW').length)}</div>
    <div class="agrid2"><div class="acard flush"><div class="toolbar"><b style="font-size:13.5px">Participanți înscriși în aplicație</b><span class="count">confirmarea acordă punctele o singură dată</span><button class="btn sm ok" data-act="confirmAll" data-arg="${cur.id}">${ms('done_all', 'xs')} Confirmă toți</button></div>${tbl(['Participant', 'Cod', 'Înscris', 'Stare', ''], regs.map(r => `<tr><td><div class="tcell">${avatarW(r.who)}<div class="tt">${esc(r.who)}</div></div></td><td><code>${r.code}</code></td><td>${r.at}</td><td>${r.status === 'CONFIRMED' ? `<span class="pill p-ok"><i></i>Confirmat · +${cur.pts}</span><div class="ts">de ${esc(r.by || 'Primărie')} ${r.when || ''}</div>` : pill(r.status)}</td><td class="row" style="gap:6px;justify-content:flex-end">${r.status === 'PENDING' ? `<button class="btn sm sec" data-act="validateW" data-arg="${r.code}:NO_SHOW">Respinge</button><button class="btn sm ok" data-act="validateW" data-arg="${r.code}:CONFIRMED">${ms('check', 'xs')} Confirmă</button>` : ''}</td></tr>`))}</div>
      <div class="col" style="gap:14px"><div class="acard"><div class="ch"><div><h2>Voluntarii care scanează</h2><div class="hint">Confirmarea pe teren se face din aplicația de telefon (rol Voluntar), nu de aici.</div></div><a class="btn sm sec" href="#/city/volunteers/new">${ms('person_add', 'xs')} Adaugă</a></div>${(() => { const vs = A.allVols().filter(v => v.actions.includes(cur.id)); return vs.length ? vs.map(v => `<div class="lrow">${avatarW(v.name, true)}<div class="grow"><b style="font-size:13.5px">${esc(v.name)}</b><div class="ts">cod ${v.code} · ${v.scans + S.scans.filter(x => x.by === v.name).length} scanări · coordonator ${esc(v.coord)}</div></div>${pill(v.status)}<button class="btn sm sec" data-act="volActions" data-arg="${v.id}">Acțiuni</button><a class="btn sm sec" href="#/city/messages?v=${v.id}">${ms('forum', 'xs')}</a></div>`).join('') : empty('badge', 'Niciun voluntar alocat', 'Alocă un voluntar ca să poată scana la această acțiune.'); })()}<div class="row" style="margin-top:10px"><input class="in grow" placeholder="Confirmă manual după cod: AX-C1-…" data-bind="vcode" data-enter="validateCode" value="${esc(UI.tmp.vcode || '')}"><button class="btn sec" data-act="validateCode">Confirmă</button></div></div>
      <div class="acard"><div class="ch"><h2>Clasament · noiembrie</h2><a class="btn sm sec" href="#/city/leaderboard">Tot</a></div>${A.BOARD.slice(0, 5).map((b, i) => `<div class="lrow"><span class="n">${i + 1}</span><span class="grow">${b[0]}</span><b>${b[1]}</b></div>`).join('')}</div></div></div>` }; });
ACT.va = a => { UI.tmp.va = a; render(); };
ACT.validateW = a => { const [code, status] = a.split(':'); const r = A.allRegs().find(x => x.code === code); const act = A.allActions().find(x => x.id === r.action); S.validations[code] = { status, by: 'Ioana Marin', when: A.NOW }; S.scans.push({ kind: 'action', code, who: r.who, by: 'Ioana Marin', at: A.NOW, status, pts: status === 'CONFIRMED' ? act.pts : 0 }); if (status === 'CONFIRMED' && r.who === 'Ana P.') S.points += act.pts; save(); toast(status === 'CONFIRMED' ? `${r.who} confirmat · +${act.pts} puncte` : `${r.who} respins`, status === 'CONFIRMED' ? 'check_circle' : 'cancel'); render(); };
ACT.confirmAll = id => { A.allRegs().filter(r => r.action === id && r.status === 'PENDING').forEach(r => ACT.validateW(r.code + ':CONFIRMED')); };
ACT.validateCode = () => { const code = (UI.tmp.vcode || '').trim().toUpperCase(); const r = A.allRegs().find(x => x.code === code); if (!r) { toast('Cod necunoscut.', 'error'); return; } if (r.status === 'CONFIRMED') { toast('Deja confirmat.'); return; } UI.tmp.vcode = ''; ACT.validateW(code + ':CONFIRMED'); };

/* ---------- Voluntari ---------- */
route('/city/volunteers', () => { const f = UI.tmp.vf || 'all'; const l = A.allVols().filter(v => f === 'all' || v.status === (f === 'active' ? 'ACTIVE' : 'SUSPENDED'));
  return { title: 'Voluntari', crumbs: ['Primăria Arad', 'Comunitate', 'Voluntari'], body: `<div class="head"><div><h1>Voluntari</h1><div class="sub">Conturile de voluntar le creezi doar tu. Voluntarii folosesc aplicația pentru scanare și mesaje.</div></div><a class="btn" href="#/city/volunteers/new">${ms('person_add', 'xs')} Adaugă voluntar</a></div>
    <div class="kpis" style="grid-template-columns:repeat(3,1fr)">${kpi('badge', 'Voluntari activi', A.allVols().filter(v => v.status === 'ACTIVE').length, '', SPARK.d, '#1D5FD1')}${kpi('qr_code_scanner', 'Scanări înregistrate', S.scans.filter(s => s.kind === 'action').length + 2, '', SPARK.c)}${kpi('task_alt', 'Acțiuni acoperite', `${A.pubActions().filter(a => A.allVols().some(v => v.actions.includes(a.id))).length}/${A.pubActions().length}`, '', SPARK.a, '#FF5A36')}</div>
    <div class="acard flush"><div class="toolbar">${segs(f, [['all', 'Toți'], ['active', 'Activi'], ['susp', 'Suspendați']], 'vf')}<span class="count">${l.length} voluntari</span></div>${tbl(['Voluntar', 'Cod de acces', 'Participă la', 'Coordonator', 'Scanări', 'Stare', ''], l.map(v => `<tr><td><div class="tcell">${avatarW(v.name, true)}<div><div class="tt">${esc(v.name)}</div><div class="ts">${v.phone}${v.oneTime ? ' · unică folosință' : ''}</div></div></div></td><td><code>${v.code}</code></td><td>${v.actions.map(id => `<div class="chip sm" style="height:24px;font-size:11.5px;max-width:190px;overflow:hidden;text-overflow:ellipsis;margin:2px 0">${esc((A.allActions().find(a => a.id === id) || {}).title || id)}</div>`).join('')}</td><td>${esc(v.coord)}</td><td>${v.scans + S.scans.filter(s => s.by === v.name).length}</td><td>${pill(v.status)}</td><td class="row" style="gap:6px;justify-content:flex-end"><button class="btn sm sec" data-act="volActions" data-arg="${v.id}">${ms('edit', 'xs')} Acțiuni</button><a class="btn sm sec" href="#/city/messages?v=${v.id}">${ms('forum', 'xs')} Mesaj</a><button class="btn sm sec" data-act="volToggle" data-arg="${v.id}" title="${v.status === 'ACTIVE' ? 'Suspendă' : 'Reactivează'}">${ms(v.status === 'ACTIVE' ? 'pause_circle' : 'play_circle', 'xs')}</button></td></tr>`))}</div>` }; });
ACT.vf = a => { UI.tmp.vf = a; render(); };
ACT.volToggle = id => { const v = A.allVols().find(x => x.id === id); A.setOverride('vo:' + id, { status: v.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE' }); toast(v.status === 'ACTIVE' ? 'Cont suspendat.' : 'Cont reactivat.'); render(); };
ACT.volActions = id => { const v = A.allVols().find(x => x.id === id); UI.form = { vols: v.actions.slice() }; drawer(`<h2>${esc(v.name)} · acțiuni alocate</h2><div class="sub">Bifează acțiunile la care scanează.</div><div style="margin-top:14px">${field('Acțiuni', 'vols', 'checks', { options: A.allActions().filter(a => a.status !== 'DRAFT').map(a => [a.id, a.title, A.dayLabel(a.date) + ' · ' + a.time]) })}</div><button class="btn lg" style="width:100%;margin-top:16px" data-act="volActionsSave" data-arg="${id}">Salvează</button>`); };
ACT.volActionsSave = id => { A.setOverride('vo:' + id, { actions: (UI.form.vols || []).slice() }); closeDrawer(); toast('Acțiuni actualizate. Voluntarul le vede în aplicație.', 'check_circle'); render(); };
ACT.fcheck = a => { const [k, v] = a.split(':'); const arr = UI.form[k] = UI.form[k] || []; const i = arr.indexOf(v); i >= 0 ? arr.splice(i, 1) : arr.push(v); if (UI.drawer) { const vid = (document.querySelector('[data-act="volActionsSave"]') || {}).dataset; if (vid) ACT.volActions(vid.arg); else render(); } else render(); };
function volPreview() { const f = UI.form; return `<div class="vcard"><div class="row"><span class="avatar" style="background:#fff;color:#111">${A.initials(f.name || 'V N')}</span><div class="grow"><b>${esc(f.name || 'Numele voluntarului')}</b><div style="font-size:12px;opacity:.7">Coordonator: ${esc(f.coord || 'Ioana Marin')}</div></div><span class="pill" style="background:var(--acc);color:#fff">Voluntar</span></div><div class="row" style="gap:8px">${[[(f.vols || []).length, 'acțiuni alocate'], [0, 'scanați'], ['—', 'de scanat']].map(x => `<div style="flex:1;background:rgba(255,255,255,.1);border-radius:10px;padding:8px"><b style="font-size:18px">${x[0]}</b><div style="font-size:11px;opacity:.7">${x[1]}</div></div>`).join('')}</div><div style="font-size:12px;opacity:.7">Cont creat de Primăria Arad${f.oneTime ? ' · de unică folosință' : ''}</div></div><div class="pcard" style="margin-top:12px;padding:14px"><div style="font-size:11px;color:#6E6E73;font-weight:700;letter-spacing:.06em">SMS (SIMULAT)</div><div style="font-size:13px;margin-top:6px">Bună, ${esc((f.name || 'voluntar').split(' ')[0])}! Primăria Arad ți-a creat cont de voluntar în AradExperience. Cod de acces: <b>${UI.tmp.newCode || '••••••'}</b></div></div>`; }
route('/city/volunteers/new', () => { if (UI.formFor !== 'vol') { UI.form = { coord: 'Ioana Marin', vols: [], oneTime: false }; UI.formFor = 'vol'; UI.tmp.newCode = String(100000 + Math.floor(Math.random() * 900000)); } UI.previewFn = volPreview;
  return { title: 'Voluntar nou', crumbs: ['Primăria Arad', 'Voluntari', 'Nou'], body: `<div class="head"><div><h1>Voluntar nou</h1><div class="sub">Voluntarul primește prin SMS un cod de 6 cifre și intră în aplicație doar cu el: vede acțiunile lui, scanează, îți scrie.</div></div></div>
    <div class="form"><div class="fcard"><div class="fsec">Persoana</div>${field('Nume', 'name', 'text', { ph: 'Prenume și nume' })}<div class="two">${field('Telefon (pentru SMS)', 'phone', 'text', { ph: '07xx xxx xxx' })}${field('E-mail (opțional)', 'email', 'email')}</div>${field('Coordonator', 'coord', 'select', { options: A.COORDS.map(c => [c, c]) })}
      <div class="fsec">Acțiuni alocate</div>${field('Participă la', 'vols', 'checks', { options: A.allActions().filter(a => a.status !== 'DRAFT').map(a => [a.id, a.title, A.dayLabel(a.date) + ' · ' + a.time]) })}${field('Cont de unică folosință', 'oneTime', 'toggle', { hint: 'Expiră automat după ultima acțiune alocată.' })}
      <div class="actions"><a class="btn sec" href="#/city/volunteers">Anulează</a><button class="btn" data-act="volSave">${ms('sms', 'xs')} Creează contul și trimite codul</button></div></div>${phonePreview(volPreview(), 'Așa apare în aplicație · SMS')}</div>` }; });
ACT.volSave = () => { const f = UI.form; if (!f.name) { toast('Scrie numele.'); return; } S.created.vols.push({ id: 'nv' + Date.now(), name: f.name, phone: f.phone || '', email: f.email || '', code: UI.tmp.newCode, coord: f.coord, actions: (f.vols || []).slice(), oneTime: !!f.oneTime, status: 'ACTIVE', scans: 0 }); save(); UI.formFor = null; toast(`Cont creat. Cod trimis prin SMS (simulat): ${UI.tmp.newCode}`, 'check_circle'); go('/city/volunteers'); };

/* ---------- Mesaje ---------- */
route('/city/messages', (p, q) => { const vols = A.allVols(); const cur = vols.find(v => v.id === (q.v || UI.tmp.mv)) || vols[0]; UI.tmp.mv = cur.id; const msgs = (A.MSGS[cur.id] || []).concat(S.msgs[cur.id] || []);
  return { title: 'Mesaje', crumbs: ['Primăria Arad', 'Comunitate', 'Mesaje'], body: `<div class="head"><div><h1>Mesaje</h1><div class="sub">Conversații cu voluntarii. Ei scriu din aplicație, tu răspunzi de aici.</div></div></div>
    <div class="acard flush asplit"><div class="l">${vols.map(v => { const m = (A.MSGS[v.id] || []).concat(S.msgs[v.id] || []); const last = m[m.length - 1]; return `<button class="litem ${v.id === cur.id ? 'on' : ''}" data-act="mv" data-arg="${v.id}">${avatarW(v.name, true)}<div class="grow" style="min-width:0"><div class="row" style="justify-content:space-between"><b style="font-size:13.5px">${esc(v.name)}</b><span class="ts">${last ? last.at : ''}</span></div><div class="ts ell">${last ? (last.from === 'vol' ? '' : 'Tu: ') + esc(last.text) : 'Fără mesaje'}</div></div>${(S.msgs[v.id] || []).some(x => x.from === 'vol') ? '<span class="dot"></span>' : ''}</button>`; }).join('')}</div>
      <div class="thread"><div class="hd">${avatarW(cur.name, true)}<div class="grow"><b>${esc(cur.name)}</b><div class="ts">Voluntar · ${cur.actions.length} acțiuni alocate · coordonator ${esc(cur.coord)}</div></div>${pill(cur.status)}</div><div class="msgs">${msgs.map(m => `<div class="bub ${m.from === 'vol' ? 'them' : 'us'}">${esc(m.text)}</div><span class="bt ${m.from === 'vol' ? '' : 'us'}">${m.at}</span>`).join('')}</div>
      <div class="composer"><div class="row" style="flex-wrap:wrap;gap:6px">${A.QUICK.map(x => `<button class="chip sm" data-act="msgSend" data-arg="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="row"><input class="in grow" placeholder="Scrie un mesaj…" data-bind="msgIn" data-enter="msgSendInput" value="${esc(UI.tmp.msgIn || '')}"><button class="btn" data-act="msgSendInput">${ms('send', 'xs')} Trimite</button></div></div></div></div>` }; });
ACT.mv = a => { UI.tmp.mv = a; render(); };
ACT.msgSend = t => { (S.msgs[UI.tmp.mv] = S.msgs[UI.tmp.mv] || []).push({ from: 'coord', text: t, at: 'azi, ' + A.NOW }); save(); render(); };
ACT.msgSendInput = () => { const t = (UI.tmp.msgIn || '').trim(); if (!t) return; UI.tmp.msgIn = ''; ACT.msgSend(t); };

