route('/city/leaderboard', () => { const per = UI.tmp.lbp || 'month'; const rows = A.BOARD.slice().sort((a, b) => b[1] - a[1]);
  return { title: 'Clasament', crumbs: ['Primăria Arad', 'Comunitate', 'Clasament'], body: `<div class="head"><div><h1>Clasamentul voluntarilor</h1><div class="sub">Puncte câștigate la acțiunile comunitare (nu cele cheltuite). Public pentru toți utilizatorii.</div></div><button class="btn sec" data-act="toast" data-arg="clasament-noiembrie-2026.csv descărcat.">${ms('download', 'xs')} Export CSV</button></div>
    <div class="agrid2"><div class="acard flush"><div class="toolbar">${segs(per, [['month', 'Noiembrie'], ['year', 'Anul 2026']], 'lbp')}<div class="asearch" style="max-width:260px">${ms('search', 's')}<input placeholder="Caută voluntar"></div></div>${tbl(['#', 'Voluntar', 'Acțiuni', 'Puncte', 'Ultima participare'], rows.map((r, i) => `<tr><td>${i < 3 ? ['🥇', '🥈', '🥉'][i] : i + 1}</td><td><div class="tcell">${avatarW(r[0])}<b>${r[0]}</b>${r[0] === 'Ana P.' ? '<span class="pill p-ok">cont demo</span>' : ''}</div></td><td>${r[2]}</td><td><b>${per === 'month' ? Math.round(r[1] * .22) : r[1]}</b></td><td>${r[3]}</td></tr>`))}</div>
      <div class="col" style="gap:14px"><div class="acard"><div class="ch"><h2>Premiile anului 2026</h2><button class="btn sm sec" data-act="na">Editează</button></div>${A.PRIZES.map((p, i) => `<div class="lrow"><span class="avatar" style="background:${['#FFE08A', '#E6E6E6', '#F0C9A8'][i]}">${i + 1}</span><div><div class="ts">${p[0]}</div><b style="font-size:13.5px">${p[1]}</b></div></div>`).join('')}<div class="ts" style="margin-top:10px">Primii 50 sunt invitați la Gala Voluntarilor, 19 decembrie.</div></div><div class="acard"><h2 style="font-size:14.5px;margin:0 0 8px">Statistici</h2><div class="lrow">${ms('group', 's')}<span>412 voluntari activi în 2026</span></div><div class="lrow">${ms('trending_up', 's')}<span>+38% față de 2025</span></div><div class="lrow">${ms('schedule', 's')}<span>2.340 de ore de voluntariat</span></div><div class="lrow">${ms('sell', 's')}<span>Puncte folosite la firme: Cafeneaua din Pasaj 72 · Brutăria Veche 51 · Bistro La Mureș 34</span></div></div></div></div>` }; });
