function offerPreview() { const f = UI.form; const b = firm(); return `<div class="pcard"><div class="pimg" style="${f.img ? `background-image:url('${f.img}')` : `background:${b.color}`}">${f.img ? '' : '☕'}<span class="pchip" style="left:12px;top:12px;background:#FFC244">${esc(f.tag || '-10%')}</span>${b.local ? '<span class="pchip" style="right:12px;top:12px;background:#fff;color:#7A4A00">🧺 Făcut în Arad</span>' : ''}</div><div class="pbody"><div class="row" style="justify-content:space-between;font-size:12.5px;color:#5C5C5C"><span>${esc(b.name)}</span><span>${b.rating} ★</span></div><b style="font-size:16px;color:${f.title ? '#111' : '#9a9a9a'}">${esc(f.title || 'Titlul ofertei')}</b><span style="font-size:12.5px;color:#5C5C5C">${A.km(b.dist)} · ${f.validUntil ? 'valabilă până ' + A.dayLabel(f.validUntil).toLowerCase() : 'permanent'}${f.pointsPrice ? ' · sau ' + f.pointsPrice + ' de puncte' : ''}</span></div></div>`; }
route('/business/offers/new', () => { if (UI.formFor !== 'offer') { UI.form = { tag: '-10%', validFrom: A.TODAY, validUntil: '2026-11-30', cat: 'cafe' }; UI.formFor = 'offer'; } UI.previewFn = offerPreview; const b = firm();
  return { title: 'Ofertă nouă', crumbs: [b.name, 'Oferte', 'Nouă'], body: `<div class="head"><div><h1>Ofertă nouă</h1><div class="sub">Clientul o revendică în aplicație și arată codul la casă; tu îl validezi o singură dată.</div></div></div><div class="form"><div class="fcard"><div class="fsec">Oferta</div>${field('Titlu', 'title', 'text', { ph: 'Ex.: 20% reducere la orice cafea' })}<div class="two">${field('Eticheta reducerii', 'tag', 'text', { ph: '-20% · 2+1 · Gratuit' })}${field('Preț în puncte (opțional)', 'pointsPrice', 'number', { ph: '30', hint: 'Localnicii pot plăti cu punctele din acțiunile comunitare.' })}</div>${field('Categorie', 'cat', 'chips', { options: [['cafe', 'Cafenele'], ['rest', 'Restaurante'], ['local', 'Făcut în Arad'], ['points', 'Doar cu puncte']] })}${field('Descriere', 'desc', 'textarea', { ph: 'Arată codul la casă. Valabil de luni până sâmbătă, o dată pe zi, pentru o comandă.' })}<div class="two">${field('Valabilă de la', 'validFrom', 'date')}${field('până la', 'validUntil', 'date')}</div><div class="fsec">Imagine</div>${field('Imagine', 'img', 'drop')}<div class="actions"><button class="btn sec" data-act="offerSave" data-arg="DRAFT">Salvează ciornă</button><button class="btn" data-act="offerSave" data-arg="PUBLISHED">${ms('publish', 'xs')} ${b.verified ? 'Publică' : 'Trimite spre publicare'}</button></div></div>${phonePreview(offerPreview())}</div>` }; });
ACT.offerSave = st => { const f = UI.form; const b = firm(); if (!f.title) { toast('Scrie un titlu.'); return; } const status = b.verified ? st : 'DRAFT'; S.created.offers.push({ id: 'no' + Date.now(), biz: b.id, title: f.title, tag: f.tag || '', kind: f.cat === 'points' ? 'points' : 'offer', cat: f.cat === 'points' ? 'points' : f.cat, validFrom: f.validFrom, validUntil: f.validUntil || null, pointsPrice: +f.pointsPrice || undefined, onlyPoints: f.cat === 'points', img: f.img || 'shared/img/oferta-cafea.jpg', views: 0, used: 0, status, desc: f.desc || '' }); save(); UI.formFor = null; toast(status === 'PUBLISHED' ? 'Ofertă publicată. Apare acum în aplicație.' : 'Salvată ca ciornă.', 'check_circle'); go('/business/offers'); };

/* ---------- Firmă: evenimente, anunțuri, coduri, recenzii, profil ---------- */
route('/business/events', () => { const b = firm(); const l = A.allEvents().filter(e => e.bizId === b.id);
  return { title: 'Evenimente', crumbs: [b.name, 'Evenimente'], body: `<div class="head"><div><h1>Evenimente</h1><div class="sub">Evenimentele tale apar în lista publică alături de cele ale instituțiilor.</div></div><a class="btn" href="#/business/events/new">${ms('add', 'xs')} Eveniment nou</a></div><div class="acard flush">${tbl(['Eveniment', 'Când', 'Bilete', 'Participă', 'Stare', ''], l.map(e => `<tr><td><div class="tcell"><div class="thumb" style="${evThumbStyle(e)}">${e.img ? '' : e.emoji}</div><div><div class="tt">${esc(e.title)}</div><div class="ts">${A.CATS[e.cat].l} · ${e.ticket === 'IN_APP' ? 'bilete în aplicație' : 'intrare liberă'}</div></div></div></td><td>${A.whenLabel(e)}</td><td>${e.ticket === 'IN_APP' ? `${A.lei(e.priceAdult)} · ${e.participants}/${e.capacity}` : 'Gratuit'}</td><td>${e.participants}${A.isHot(e) ? ' 🔥' : ''}</td><td>${pill(e.status || 'PUBLISHED')}</td><td class="row" style="gap:6px;justify-content:flex-end">${(e.status || 'PUBLISHED') !== 'PUBLISHED' ? `<button class="btn sm" data-act="setStatus" data-arg="ev:${e.id}:PUBLISHED" ${b.verified ? '' : 'disabled'}>Publică</button>` : ''}<button class="btn sm sec" data-act="na">Editează</button></td></tr>`))}</div><div class="acard" style="margin-top:14px"><b>Scanare bilete la intrare</b><div class="sub">La evenimentele cu bilete, validezi biletele cu scanner-ul (POST /tickets/{code}/use). Fiecare cod merge o singură dată.</div><a class="btn sec" style="margin-top:10px" href="#/business/codes">${ms('qr_code_scanner', 'xs')} Deschide scanner-ul</a></div>` }; });
route('/business/events/new', () => { const r = ROUTES.find(x => x.pattern === '/city/events/new'); const out = r.fn({}, {}); out.crumbs = [firm().name, 'Evenimente', 'Nou']; return out; });
route('/business/announcements', () => { const b = firm(); const l = A.allAnn().filter(a => a.biz === b.id);
  return { title: 'Anunțuri', crumbs: [b.name, 'Anunțuri'], body: `<div class="head"><div><h1>Anunțuri</h1><div class="sub">Scurte, fără dată de eveniment: program, noutăți, angajări. Apar pe pagina firmei și în feed-ul „Lângă mine”.</div></div><button class="btn" data-act="annNew">${ms('add', 'xs')} Anunț nou</button></div><div class="agrid2"><div>${l.map(a => `<div class="acard row" style="gap:14px;margin-bottom:10px;${a.expired ? 'opacity:.6' : ''}"><div class="grow"><b>${esc(a.title)}</b><div class="ts">${esc(a.text)}</div><div class="ts">${a.at} · ${a.views} vizualizări</div></div>${a.expired ? '<button class="btn sm sec" data-act="na">Republică</button>' : `<button class="btn sm sec" data-act="na">Editează</button><button class="btn sm sec" data-act="na">${ms('delete', 'xs')}</button>`}</div>`).join('')}</div>${UI.tmp.annForm ? `<div class="fcard"><div class="row" style="justify-content:space-between"><b>Anunț nou</b><button class="chip sm" data-act="annNew">${ms('close', 'xs')}</button></div>${field('Titlu', 'atitle', 'text', { ph: 'Prăjim un lot nou de Etiopia' })}${field('Text', 'atext', 'textarea', { ph: 'De joi avem un lot nou…' })}${field('Imagine (opțional)', 'aimg', 'drop')}<div class="actions"><button class="btn sec" data-act="annNew">Anulează</button><button class="btn" data-act="annSave">Publică</button></div></div>` : ''}</div>` }; });
ACT.annNew = () => { UI.tmp.annForm = !UI.tmp.annForm; UI.form = {}; render(); };
ACT.annSave = () => { if (!UI.form.atitle) { toast('Scrie un titlu.'); return; } S.created.ann.push({ id: 'na' + Date.now(), biz: firm().id, title: UI.form.atitle, text: UI.form.atext || '', at: 'acum', views: 0 }); save(); UI.tmp.annForm = false; toast('Anunț publicat.', 'check_circle'); render(); };
route('/business/codes', () => { const b = firm(); const today = S.scans.filter(s => s.kind === 'offer').slice().reverse().map(s => { const c = S.claims.find(x => x.code === s.code) || {}; const o = A.allOffers().find(x => x.id === c.offerId) || {}; return [s.at, s.code, o.title || '—', 'Ana P.', c.points ? c.points + ' p' : '—']; }).concat([['09:58', 'AX-O2-M2N8RT', 'Prăjitura zilei -10%', 'Elena T.', '—'], ['09:12', 'AX-O1-B9Q2LW', 'Cafea -20%', 'Radu M.', '—'], ['ieri 18:30', 'AX-O3-Q5W7ZX', 'Cappuccino cu puncte', 'Mihai R.', '40 p']]);
  return { title: 'Validează coduri', crumbs: [b.name, 'Validează coduri'], body: `<div class="head"><div><h1>Validează coduri</h1><div class="sub">Codul de pe telefonul clientului (QR sau text). Devine „folosit” o singură dată; la ofertele cu puncte, punctele au fost deja debitate la revendicare.</div></div></div><div class="agrid2" style="grid-template-columns:380px minmax(0,1fr)"><div class="acard"><b>Validează un cod</b><div class="sub" style="margin-bottom:10px">Scanarea QR se face din aplicația de telefon (Panou › Validează un cod), la casă. Aici introduci codul de pe telefonul clientului.</div><div class="row"><input class="in grow" placeholder="AX-O1-…" data-bind="bcode" data-enter="bValidate" value="${esc(UI.tmp.bcode || '')}"><button class="btn" data-act="bValidate">Validează</button></div>${S.claims.some(c => !c.used) ? `<button class="btn sec" style="margin-top:8px;width:100%" data-act="bSim">Simulează scanarea unui cod activ</button>` : '<div class="ts" style="margin-top:8px">Niciun cod activ în acest browser: revendică o ofertă din aplicație (rol Localnic) și revino.</div>'}</div><div class="acard flush"><div class="toolbar"><b style="font-size:13.5px">Coduri folosite azi (${today.length})</b></div>${tbl(['Ora', 'Cod', 'Ofertă', 'Client', 'Puncte'], today.map(r => `<tr><td>${r[0]}</td><td><code>${r[1]}</code></td><td>${esc(r[2])}</td><td>${r[3]}</td><td>${r[4] === '—' ? '—' : `<span class="pill p-ok">${r[4]}</span>`}</td></tr>`))}</div></div>` }; });
ACT.bSim = () => { const c = S.claims.find(x => !x.used); if (c) { UI.tmp.bcode = c.code; ACT.bValidate(); } };
route('/business/reviews', () => { const b = firm(); const rv = A.BIZ_REVIEWS[b.id] || [];
  return { title: 'Recenzii', crumbs: [b.name, 'Recenzii'], body: `<div class="head"><div><h1>Recenzii</h1><div class="sub">Păreri lăsate în aplicație la firmă și la evenimentele tale. Media firmei = media evenimentelor + ofertelor.</div></div></div><div class="agrid2"><div>${rv.map(r => `<div class="acard" style="margin-bottom:10px"><div class="row" style="justify-content:space-between"><div class="tcell">${avatarW(r.who)}<b>${esc(r.who)}</b></div><span class="stars">${stars(r.stars)}</span></div><div style="margin-top:8px">„${esc(r.text)}”</div><div class="row" style="justify-content:space-between;margin-top:8px"><span class="ts">${r.at}</span><button class="btn sm sec" data-act="na">Răspunde</button></div></div>`).join('') || empty('reviews', 'Nicio recenzie încă')}</div><div class="acard"><b style="font-size:34px;letter-spacing:-.03em">${b.rating}</b><div class="stars">${stars(b.rating)}</div><div class="ts">${b.reviews} păreri · pe Google: ★ 4,6 (1.240) <span class="pill p-mut">opțional T17</span></div>${[5, 4, 3, 2, 1].map(n => `<div class="hbar" style="grid-template-columns:20px 1fr 36px;margin-top:8px"><span class="ts">${n}★</span><div class="bar"><i style="width:${[70, 20, 6, 3, 1][5 - n]}%"></i></div><span class="ts">${[70, 20, 6, 3, 1][5 - n]}%</span></div>`).join('')}</div></div>` }; });
route('/business/profile', () => { const b = firm(); return { title: 'Profilul firmei', crumbs: [b.name, 'Profilul firmei'], body: `<div class="head"><div><h1>Profilul firmei</h1><div class="sub">Ce văd oamenii pe pagina ta publică și pe hartă.</div></div><a class="btn sec" href="#/businesses/${b.id}">${ms('visibility', 'xs')} Pagina mea publică</a></div><div class="form"><div class="fcard"><div class="fsec">Firma</div><div class="two"><div class="f"><label>Nume</label><input class="in" value="${esc(b.name)}"></div><div class="f"><label>Categorie</label><input class="in" value="${esc(b.cat)}"></div></div><div class="f"><label>Adresa (pe hartă)</label><input class="in" value="${esc(b.addr)}, Arad · ${b.lat}, ${b.lng}"></div><div class="f"><label>Descriere</label><textarea class="in">${esc(b.tagline)}</textarea></div><div class="two"><div class="f"><label>Program</label><input class="in" value="${esc(b.hours)}"></div><div class="f"><label>Telefon</label><input class="in" value="${b.phone}"></div></div><div class="f"><label>Etichete</label><div class="chips">${b.tags.map(t => `<span class="chip sm">${esc(t)}</span>`).join('')}</div></div><div class="toggle ${b.local ? 'on' : ''}"><span><b style="font-size:13.5px">Producător local · „Făcut în Arad”</b></span><span class="sw2"></span></div><div class="actions"><button class="btn" data-act="toast" data-arg="Profil salvat.">Salvează</button></div></div><div class="acard"><div class="thumb" style="width:100%;height:160px;border-radius:12px;background-image:url('${b.img}')"></div><div class="ts" style="margin-top:8px">${esc(b.credit || '')}</div><div class="kv" style="margin-top:8px">${ms('verified')}<span>${b.verified ? 'Cont verificat de Primăria Arad' : 'În așteptarea verificării'}</span></div><div class="kv">${ms('calendar_month')}<span>Partener din ${b.since}</span></div></div></div>` }; });
